SELECT 'gongkao', '估算速算', 'kp-xingce-data-calc-estimation', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "估算速算综合"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "利用数据尾数、高位截取、乘法补偿等手段快速锁定答案量级的方法。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "常用于多项数据连加（求总额）、连乘或包含微小扰动项的复杂综合算式。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心结论"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 加减尾数法：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 选项末尾数字各不相同时，只把题干数据的最后一位相加减。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 乘法一进一舍：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A×B估算时，若A向上进位，B应向下舍去，以平衡误差。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出复杂连加/连乘算式] --> B[先扫一眼选项的特征]\nB -- 选项尾数均不同 --> C[直接取每个数最后一位相加算尾数]\nB -- 选项首位差异大 --> D[每个数从左数保留两到三位截断]\nC --> E[对照选项秒选]\nD --> E"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 某市四个区GDP分别为 1234, 5678, 2345, 8765。求全市GDP总量？选项：A. 17920  B. 18022  C. 18125  D. 18228"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：典型的多项连加，且选项最后一位分别为 0, 2, 5, 8，完全不同！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "启动尾数法：不加全数，只加尾数 4 + 8 + 5 + 5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "计算尾数：4+8=12，尾数2；2+5=7；7+5=12，最终尾数为 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定选项：唯一尾数为 2 的是选项 B。耗时 5 秒。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "加减混合时小数点未对齐：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "使用尾数法或高位截取法时，很多考生忽略了小数点。比如 12.3 + 4.56，你拿 3 和 6 去加得出 9，大错特错！必须补齐为 12.30 + 4.56，尾数是 0+6=6。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "平时练习绝对不要用计算器。碰到连加题，强迫自己必须看选项尾数，逼自己走捷径。"}]}]}$$ AS jsonb), NULL, '估算速算的核心考点与实战推导。', category_node.id, CAST('["资料分析", "估算速算"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_calc_estimation", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
